out_dir = os.path.join(os.path.dirname(__file__), '..', 'www', 'js')
for r in ROWS:
    assert len(r) == 1 + len(LANGS), f'ligne incomplète : {r[0][:40]} ({len(r)})'
for k, code in enumerate(LANGS):
    d = {r[0]: r[k + 1] for r in ROWS}
    body = ',\n'.join(f'  {json.dumps(fr, ensure_ascii=False)}: {json.dumps(tx, ensure_ascii=False)}' for fr, tx in d.items())
    with open(os.path.join(out_dir, f'i18n-{code}.js'), 'w', encoding='utf-8') as f:
        f.write(f'// Fichier généré par scripts/i18n-core.py — modifiez ce script, pas ce fichier.\nexport const DICT = {{\n{body},\n}};\n')
print(f'✓ {len(LANGS)} langues, {len(ROWS)} textes chacune')
